-- CLEANING SERVICES - Invoice With Photos
--
-- A billing document rather than a site report: company/invoice-meta
-- header, a "Bill To" block, an itemized services table with a bold TOTAL
-- row, an additional-charges table, subtotal/tax/total lines, payment terms
-- and instructions, then a "Photos of Completed Work" section with two
-- labeled before/after photo pairs plus a single PPE-disposal-area slot.
-- Every field is a literal [bracket] placeholder to hand-fill (matching the
-- other CLEANING SERVICES / ADJUSTING templates) rather than this app's
-- {{token}} merge system -- there's no natural per-project company/invoice
-- data to auto-fill here the way there is for project_name/date elsewhere.
INSERT INTO public.document_templates (slug, team_id, created_by, name, body, fields)
VALUES (
  'example-cleaning-invoice-with-photos',
  NULL,
  NULL,
  'CLEANING SERVICES - Invoice With Photos',
  jsonb_build_object(
    'style', 'report',
    'description', 'Itemized invoice with company/bill-to details, payment terms and instructions, and before/after completion photos.',
    'html', $html$<h1>CLEANING SERVICES - Invoice With Photos</h1><h2>Company Details</h2><p><strong>[Your Company Name]</strong></p><p>[Address] &ndash; Phone: [###-###-####] &ndash; Email: [<a href="mailto:info@company.com">info@company.com</a>]</p><p>Website: [URL]</p><table><tbody><tr><th><p>Invoice No.</p></th><td><p>[####]</p></td></tr><tr><th><p>Date</p></th><td><p>[MM/DD/YY]</p></td></tr><tr><th><p>Due Date</p></th><td><p>[MM/DD/YY]</p></td></tr></tbody></table><hr><p><strong>Bill To:</strong></p><p>[Client Name]</p><p>[Site Address]</p><p>Phone: [###-###-####] &ndash; Email: [<a href="mailto:client@email.com">client@email.com</a>]</p><hr><h2>Description of Services Provided</h2><table><tbody><tr><th><p>Item No.</p></th><th><p>Description of Work / Service</p></th><th><p>Quantity / Hours</p></th><th><p>Unit Price</p></th><th><p>Total</p></th></tr><tr><td><p>001</p></td><td><p>Post-Construction Debris Removal</p></td><td><p>[Qty]</p></td><td><p>[Price]</p></td><td><p>[Total]</p></td></tr><tr><td><p>002</p></td><td><p>HEPA Vacuum &amp; Wipe-Down</p></td><td><p>[Qty]</p></td><td><p>[Price]</p></td><td><p>[Total]</p></td></tr><tr><td><p>003</p></td><td><p>Disinfection Fogging</p></td><td><p>[Qty]</p></td><td><p>[Price]</p></td><td><p>[Total]</p></td></tr><tr><td><p><strong>TOTAL</strong></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p>[Total]</p></td></tr></tbody></table><p><strong>Additional Charges (if applicable)</strong></p><table><tbody><tr><th><p>Description</p></th><th><p>Amount</p></th></tr><tr><td><p>PPE Fee</p></td><td><p>[Amount]</p></td></tr><tr><td><p>Dump Fees</p></td><td><p>[Amount]</p></td></tr><tr><td><p>Misc.</p></td><td><p>[Amount]</p></td></tr></tbody></table><p><strong>Subtotal:</strong> [Subtotal]</p><p><strong>Sales Tax ( X % ):</strong> [Tax]</p><p><strong>Total Amount Due:</strong> [Total Due]</p><hr><p><strong>Payment Terms</strong></p><ul><li><p>Net [X] days from invoice date.</p></li><li><p>Late payments may incur a [X]% fee after [X] days.</p></li></ul><p><strong>Payment Instructions</strong></p><p>Make payment to:</p><p><strong>Bank:</strong> [Bank Name]</p><p><strong>Account Name:</strong> [Business Name]</p><p><strong>Routing / Account #:</strong> [####]</p><p><strong>Pay via:</strong> (check, ACH, credit card, or <strong>tap + Payment Request</strong> in Pages)</p><hr><h2>Photos of Completed Work</h2><p>Please find below the photos of the completed cleaning activities.</p><p><strong>Before / After 1</strong> <em><span style="color: rgb(156,163,175)">[INSERT DESCRIPTION]</span></em></p><p><img src="data:image/svg+xml;utf8,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20width%3D'220'%20height%3D'280'%3E%3Crect%20x%3D'0.5'%20y%3D'0.5'%20width%3D'219'%20height%3D'279'%20rx%3D'6'%20fill%3D'rgb(244%2C245%2C247)'%20stroke%3D'rgb(203%2C208%2C216)'%20stroke-dasharray%3D'5%204'%2F%3E%3Ctext%20x%3D'110'%20y%3D'132'%20font-family%3D'sans-serif'%20font-size%3D'14'%20font-weight%3D'700'%20fill%3D'rgb(107%2C114%2C128)'%20text-anchor%3D'middle'%3EPhoto%201%3C%2Ftext%3E%3Ctext%20x%3D'110'%20y%3D'152'%20font-family%3D'sans-serif'%20font-size%3D'11'%20fill%3D'rgb(156%2C163%2C175)'%20text-anchor%3D'middle'%3EClick%20to%20add%3C%2Ftext%3E%3C%2Fsvg%3E" width="48%" height="280" alt="Photo slot 1"><img src="data:image/svg+xml;utf8,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20width%3D'220'%20height%3D'280'%3E%3Crect%20x%3D'0.5'%20y%3D'0.5'%20width%3D'219'%20height%3D'279'%20rx%3D'6'%20fill%3D'rgb(244%2C245%2C247)'%20stroke%3D'rgb(203%2C208%2C216)'%20stroke-dasharray%3D'5%204'%2F%3E%3Ctext%20x%3D'110'%20y%3D'132'%20font-family%3D'sans-serif'%20font-size%3D'14'%20font-weight%3D'700'%20fill%3D'rgb(107%2C114%2C128)'%20text-anchor%3D'middle'%3EPhoto%202%3C%2Ftext%3E%3Ctext%20x%3D'110'%20y%3D'152'%20font-family%3D'sans-serif'%20font-size%3D'11'%20fill%3D'rgb(156%2C163%2C175)'%20text-anchor%3D'middle'%3EClick%20to%20add%3C%2Ftext%3E%3C%2Fsvg%3E" width="48%" height="280" alt="Photo slot 2"></p><p><strong>Before / After 2</strong> <em><span style="color: rgb(156,163,175)">[INSERT DESCRIPTION]</span></em></p><p><img src="data:image/svg+xml;utf8,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20width%3D'220'%20height%3D'280'%3E%3Crect%20x%3D'0.5'%20y%3D'0.5'%20width%3D'219'%20height%3D'279'%20rx%3D'6'%20fill%3D'rgb(244%2C245%2C247)'%20stroke%3D'rgb(203%2C208%2C216)'%20stroke-dasharray%3D'5%204'%2F%3E%3Ctext%20x%3D'110'%20y%3D'132'%20font-family%3D'sans-serif'%20font-size%3D'14'%20font-weight%3D'700'%20fill%3D'rgb(107%2C114%2C128)'%20text-anchor%3D'middle'%3EPhoto%203%3C%2Ftext%3E%3Ctext%20x%3D'110'%20y%3D'152'%20font-family%3D'sans-serif'%20font-size%3D'11'%20fill%3D'rgb(156%2C163%2C175)'%20text-anchor%3D'middle'%3EClick%20to%20add%3C%2Ftext%3E%3C%2Fsvg%3E" width="48%" height="280" alt="Photo slot 3"><img src="data:image/svg+xml;utf8,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20width%3D'220'%20height%3D'280'%3E%3Crect%20x%3D'0.5'%20y%3D'0.5'%20width%3D'219'%20height%3D'279'%20rx%3D'6'%20fill%3D'rgb(244%2C245%2C247)'%20stroke%3D'rgb(203%2C208%2C216)'%20stroke-dasharray%3D'5%204'%2F%3E%3Ctext%20x%3D'110'%20y%3D'132'%20font-family%3D'sans-serif'%20font-size%3D'14'%20font-weight%3D'700'%20fill%3D'rgb(107%2C114%2C128)'%20text-anchor%3D'middle'%3EPhoto%204%3C%2Ftext%3E%3Ctext%20x%3D'110'%20y%3D'152'%20font-family%3D'sans-serif'%20font-size%3D'11'%20fill%3D'rgb(156%2C163%2C175)'%20text-anchor%3D'middle'%3EClick%20to%20add%3C%2Ftext%3E%3C%2Fsvg%3E" width="48%" height="280" alt="Photo slot 4"></p><p>PPE Disposal Area</p><p><img src="data:image/svg+xml;utf8,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20width%3D'220'%20height%3D'280'%3E%3Crect%20x%3D'0.5'%20y%3D'0.5'%20width%3D'219'%20height%3D'279'%20rx%3D'6'%20fill%3D'rgb(244%2C245%2C247)'%20stroke%3D'rgb(203%2C208%2C216)'%20stroke-dasharray%3D'5%204'%2F%3E%3Ctext%20x%3D'110'%20y%3D'132'%20font-family%3D'sans-serif'%20font-size%3D'14'%20font-weight%3D'700'%20fill%3D'rgb(107%2C114%2C128)'%20text-anchor%3D'middle'%3EPhoto%205%3C%2Ftext%3E%3Ctext%20x%3D'110'%20y%3D'152'%20font-family%3D'sans-serif'%20font-size%3D'11'%20fill%3D'rgb(156%2C163%2C175)'%20text-anchor%3D'middle'%3EClick%20to%20add%3C%2Ftext%3E%3C%2Fsvg%3E" width="48%" height="280" alt="Photo slot 5"></p><hr><h2>Thank You</h2><p>Thank you for your business! If you have any questions, contact us at the details above.</p>$html$
